---@param config act_timetoken_lev_config_cell
function TimeTokenData:SetDataByTimeConfig(config)
    self.id = config.C_ID
    self.tokenid = config.tokenid
    self.lev = config.lev
    self.nextexp = config.nextexp
    local tempList= stringSplit(config.awardids,':')
    for i, v in ipairs(tempList) do
        self.awardids[i]=tonumber(v)
    end
    tempList= stringSplit(config.awardnums,':')
    for i, v in ipairs(tempList) do
        self.awardnums[i]=tonumber(v)
    end
    tempList= stringSplit(config.hawardids,':')
    for i, v in ipairs(tempList) do
        self.hawardids[i]=tonumber(v)
    end
    tempList= stringSplit(config.hawardnums,':')
    for i, v in ipairs(tempList) do
        self.hawardnums[i]=tonumber(v)
    end
    self.ispreviewbonus=config.ispreviewbonus==1
end

