function TimeTokenManager:InitActTimeTokenTable(timeTokenDataList)-----
    if  self.curConfig == TimeTokenConfigDefault.HalfAnniversaryTimeToken then
        local tab = ClientDataManager:Get():GetDataTable(ConfigNames.act_timetoken_lev_config)
         ---@type act_timetoken_lev_config
        local configTab = tab.GetConfigData()
        for i = 1, #configTab do
            if configTab[i].tokenid==self.curConfig.actId then
                local data = TimeTokenData()
                data:SetDataByTimeConfig(configTab[i])
                table.insert(timeTokenDataList,data)
            end
        end
    end
end

