---@return table<number,RewardData>
function TimeTokenManager:GetCostTimeTokenAwardTable(_startLev,_targetLev)
    local timeTokenTable = self:GetTimeTokenTable()
    local targetLev =_targetLev and _targetLev or self.TimeTokenInfoDataTab[self.curConfig.actId].lev
    local startLev=_startLev==nil and 1 or _startLev
    local GetNow = {}
    local GetWill = {}
    for i = 1, #timeTokenTable do
        if timeTokenTable[i].lev>=startLev and timeTokenTable[i].lev <= targetLev then
            for j = 1, #timeTokenTable[i].hawardids do
                if GetNow[timeTokenTable[i].hawardids[j]] == nil then
                    GetNow[timeTokenTable[i].hawardids[j]] = timeTokenTable[i].hawardnums[j]
                else
                    GetNow[timeTokenTable[i].hawardids[j]] = GetNow[timeTokenTable[i].hawardids[j]] +  timeTokenTable[i].hawardnums[j]
                end
            end
        elseif timeTokenTable[i].lev > targetLev then
            for j = 1, #timeTokenTable[i].hawardids do
                if GetWill[timeTokenTable[i].hawardids[j]] == nil then
                    GetWill[timeTokenTable[i].hawardids[j]] = timeTokenTable[i].hawardnums[j]
                else
                    GetWill[timeTokenTable[i].hawardids[j]] = GetWill[timeTokenTable[i].hawardids[j]] +  timeTokenTable[i].hawardnums[j]
                end
            end
        end
    end
    local GetNowList = {}
    local GetWillList = {}
    for k, v in pairs(GetNow) do
        local data = RewardData()
        data:SetDataIdNum(k, v)
        table.insert(GetNowList, data)
    end
    for k, v in pairs(GetWill) do
        local data = RewardData()
        data:SetDataIdNum(k, v)
        data:SetTypeAndQuality()
        table.insert(GetWillList, data)
    end
    table.sort(GetWillList,function(a, b)
        return a.type<b.type
    end)
    table.sort(GetWillList,function(a, b)
        return a.quality>b.quality
    end)
    return GetNowList,GetWillList
end

---@return TimeTokenInfoData
