---@param msg SC_TaskGift
function TimeTokenManager:RefreshTaskData(msg)
    self:GetTimeTokenInfoData():SetDataByMsg(msg.curTimeToken)
    for _, taskData in pairs(self:GetTimeTaskTable())  do
        if  taskData.taskId == msg.missionId[1] then
            taskData.status = 3
        end
    end
    self.TimeTaskDataTab[self.curConfig.actId] = self:TaskSortTaskByState(self.TimeTaskDataTab[self.curConfig.actId])
end

---@param curTasks SC_UserTask[]
function TimeTokenManager:SetTaskData(curTasks)
    if curTasks and #curTasks>0 then
        local taskType = curTasks[1].tasktype
        for i, config in pairs(TimeTokenConfigDefault) do
            if config.taskType==taskType then
                ---@type TaskData[]
                self.TimeTaskDataTab[config.actId]={}
                for i = 1, #curTasks do
                    local data = TaskData()
                    data:SetData_Task(curTasks[i])
                    table.insert(self.TimeTaskDataTab[config.actId],data)
                end
                self.TimeTaskDataTab[config.actId] = self:TaskSortTaskByState(self.TimeTaskDataTab[config.actId])
            end
        end
    end
end

function TimeTokenManager:TaskSortTaskByState(list)
    local tempDic = {}
    if list == nil then
        return
    end
    for i = 1, #list do
        if tempDic[list[i].status] == nil then
            tempDic[list[i].status] = {}
        end
        table.insert(tempDic[list[i].status], list[i])
    end
    if tempDic[TaskStatus.IsRally] ~= nil and #tempDic[TaskStatus.IsRally] > 0 then
        table.sort(tempDic[TaskStatus.IsRally], function(a, b)
            return a.finshNum / a.progress > b.finshNum / b.progress
        end)
    end

    if tempDic[TaskStatus.IsDoneNoGet] ~= nil then
        local temp = tempDic[TaskStatus.IsRally]
        tempDic[TaskStatus.IsRally] = tempDic[TaskStatus.IsDoneNoGet]
        tempDic[TaskStatus.IsDoneNoGet] = temp
    end
    local result = {}
    for k, v in pairs(tempDic) do
        for j = 1, #v do
            table.insert(result, v[j])
        end
    end
    return result
end

---@return table<number,TaskData>
function TimeTokenManager:GetTimeTaskTable()
    return self.TimeTaskDataTab[self.curConfig.actId]
end

---@param msg SC_ActTimeToken
function TimeTokenManager:SetInfoDataByActToken(msg)
    if self.TimeTokenInfoDataTab[msg.tokenid] == nil then
        self.TimeTokenInfoDataTab[msg.tokenid] = TimeTokenInfoData()
    end
    self.TimeTokenInfoDataTab[msg.tokenid]:SetDataByMsg(msg)
    self.TimeTokenInfoDataTab[msg.tokenid]:SetMaxLev(#self.TimeTokenDataTab[msg.tokenid])
    if self.TimeTokenDataTab[msg.tokenid] then
        for i = 1, #msg.ifgift do
            self.TimeTokenDataTab[msg.tokenid][i]:SetIfGiftValue(tonumber(msg.ifgift[i]))
            if self.TimeTokenInfoDataTab[msg.tokenid].lev == self.TimeTokenDataTab[msg.tokenid][i].lev then
                self.TimeTokenInfoDataTab[msg.tokenid]:SetNextExp(self.TimeTokenDataTab[msg.tokenid][i].nextexp)
            end
        end
    else
        error("TimeTokenDataTab 限时通行证没有该id ：",msg.tokenid)
    end
end


